const raw = $input.first().json.body || $input.first().json;

const parseList = (val, fallback = []) => {
  if (Array.isArray(val)) return val.map(String).map(s => s.trim()).filter(Boolean);
  if (typeof val === 'string') return val.split(',').map(s => s.trim()).filter(Boolean);
  return fallback;
};

const email = String(raw.email || raw['Email Address'] || '').trim().toLowerCase();
const fullName = String(raw.full_name || raw['Full Name'] || '').trim();
const targetTitles = parseList(raw.target_job_titles || raw['Target Job Titles (comma-separated)']);
const skills = parseList(raw.technical_skills || raw['Technical Skills (comma-separated)']);
const locations = parseList(raw.preferred_locations || raw['Preferred Locations (comma-separated)'], ['Remote']);

const errors = [];
if (!email || !email.includes('@')) errors.push('Valid email is required');
if (!fullName) errors.push('Full name is required');
if (targetTitles.length === 0) errors.push('At least one target job title is required');
if (skills.length === 0) errors.push('At least one technical skill is required');

const minScore = Number(raw.min_match_score ?? raw['Minimum Match Score (default 70)'] ?? 70);
const maxJobs = Number(raw.max_jobs_per_run ?? raw['Maximum Jobs Per Run'] ?? 15);

return [{
  json: {
    is_valid: errors.length === 0,
    validation_errors: errors,
    email,
    full_name: fullName,
    phone: raw.phone || null,
    schedule_enabled: raw.schedule_enabled !== undefined ? Boolean(raw.schedule_enabled) : true,
    target_job_titles: targetTitles,
    years_of_experience: Number(raw.years_of_experience ?? raw['Years of Experience'] ?? 5),
    technical_skills: skills,
    preferred_locations: locations,
    work_modes: parseList(raw.work_modes, ['remote', 'hybrid']),
    work_authorization: raw.work_authorization || raw['Work Authorization'] || null,
    employment_types: parseList(raw.employment_types || raw['Employment Types (full-time, contract, internship)'], ['full-time']),
    salary_min: raw.salary_min ? Number(raw.salary_min) : null,
    salary_max: raw.salary_max ? Number(raw.salary_max) : null,
    salary_currency: raw.salary_currency || raw['Salary Currency'] || 'USD',
    seniority_levels: parseList(raw.seniority || raw.seniority_levels || raw['Seniority (junior, mid-level, senior, lead)'], ['senior']),
    preferred_companies: parseList(raw.preferred_companies || raw['Preferred Companies (comma-separated)'], []),
    excluded_companies: parseList(raw.excluded_companies || raw['Excluded Companies (comma-separated)'], []),
    notice_period: raw.notice_period || raw['Notice Period'] || '2 weeks',
    resume_output_format: String(raw.resume_output_format || raw['Resume Output Format (docx, pdf, both)'] || 'both').toLowerCase(),
    notification_method: String(raw.notification_method || raw['Notification Method (email, slack, telegram)'] || 'email').toLowerCase(),
    notification_target: raw.notification_target || email,
    search_frequency: String(raw.search_frequency || raw['Search Frequency (daily, weekdays, weekly)'] || 'daily').toLowerCase(),
    max_jobs_per_run: Math.min(Math.max(maxJobs, 1), 100),
    min_match_score: Math.min(Math.max(minScore, 0), 100),
    structured_resume: raw.structured_resume || null,
    resume_base64: raw.resume_base64 || null,
    resume_filename: raw.resume_filename || 'Uploaded_Master_Resume.docx'
  }
}];

